376	  private _resolveTransitionWindowValue<
377	    TSceneKey extends string,
378	    TSheetId extends string,
379	  >(
380	    sceneKey: TSceneKey | null,
381	    progress: number,
382	    sheetId: TSheetId | null,
383	    window: SceneProgressTransitionWindow<TSceneKey, TSheetId>,
384	  ): number | null {
385	    if (sceneKey !== window.sceneKey) return null;
386	    if (sheetId !== window.sheetId) return null;
387	    const normalizedProgress = Helpers.remap01(
388	      progress,
389	      window.start,
390	      window.end,
391	    );
392	    const easedProgress = this._applyTransitionEase(
393	      normalizedProgress,
394	      window.easing ?? "linear",
395	    );
396	    return Helpers.lerpClamped(window.from, window.to, easedProgress);
397	  }
